# Own-words summaries of non-SRD spells (A–F). Format: name: (casting time, range, components, duration, what it does, more mana)
# 'more mana' is what changes when cast at a higher level; the app adds the mana costs.
NOTES = {
"Withering Gale": ("1 action", "150 feet", "V, S, M (a bit of sponge)", "Instantaneous",
  "You draw the water out of every creature in a 30-foot cube. Each makes a Constitution save, taking 12d8 necrotic damage on a failure or half on a success. Plants and water elementals save with disadvantage and take maximum damage. Nonmagical plants in the area that aren't creatures wither and die.", ""),
"Absorb Elements": ("1 reaction, when you take acid, cold, fire, lightning or thunder damage", "Self", "S", "1 round",
  "You catch some of the incoming energy. You have resistance to that damage type against the triggering hit and until the start of your next turn. The first time you hit with a melee attack on your next turn, it deals an extra 1d6 damage of that type.", "The extra melee damage rises by 1d6 for each level above 1st."),
"Scorching Line": ("1 action", "30 feet", "V, S, M (a red dragon's scale)", "Instantaneous",
  "A 30-foot line of roaring flame, 5 feet wide, runs from you in a direction you choose. Each creature in the line makes a Dexterity save, taking 3d8 fire damage on a failure or half on a success.", "Damage rises by 1d8 for each level above 2nd."),
"Air Bubble": ("1 action", "60 feet", "S", "24 hours",
  "A bubble of fresh air surrounds the head of up to one willing creature you can see (more with more mana). It can breathe normally in water or in airless space for the duration.", "One more creature for each level above 2nd."),
"Antagonize": ("1 action", "30 feet", "V, S, M (a playing card bearing a rival's face)", "Instantaneous",
  "You whisper something cutting to a creature you can see. It makes a Wisdom save. On a failure it takes 4d4 psychic damage and must immediately use its reaction to make a melee attack against another creature of your choice that you can see; if it can't, it has disadvantage on its next attack before the end of its next turn. On a success it takes half damage only.", "Damage rises by 1d4 for each level above 3rd."),
"Arcane Gate": ("1 action", "500 feet", "V, S", "Concentration, up to 10 minutes",
  "You open two linked portals, each a 10-foot circle: one on the ground within 10 feet of you, one within range. Anything stepping into one comes out of the other. Each portal has a front, which you choose; only the front works. On your turn you can rotate the rings as a bonus action.", ""),
"Arcane Vigor": ("1 bonus action", "Self", "V, S", "Instantaneous",
  "You tap your own life force: spend up to two of your Hit Dice and regain hit points equal to the roll plus your spellcasting modifier.", "You can spend one more Hit Die for each level above 2nd."),
"Armor of Agathys": ("1 action", "Self", "V, S, M (a cup of water)", "1 hour",
  "A frost-skinned ward covers you. You gain 5 temporary hit points. While they last, any creature that hits you with a melee attack takes 5 cold damage.", "Both the temporary hit points and the cold damage rise by 5 for each level above 1st."),
"Arms of Hadar": ("1 action", "Self (10-foot radius)", "V, S", "Instantaneous",
  "Dark tendrils burst out of you. Each creature within 10 feet makes a Strength save. On a failure it takes 2d6 necrotic damage and can't take reactions until its next turn. On a success it takes half damage only.", "Damage rises by 1d6 for each level above 1st."),
"Ashen Stride": ("1 bonus action", "Self", "V, S", "Concentration, up to 1 minute",
  "Flames trail your steps. Your speed rises by 20 feet, moving doesn't provoke opportunity attacks, and each creature or object you first move within 5 feet of on a turn takes 1d6 fire damage.", "Speed rises by 5 more feet and fire by 1d6 for each level above 3rd."),
"Aura of Purity": ("1 action", "Self (30-foot radius)", "V", "Concentration, up to 10 minutes",
  "A purifying aura surrounds you. Friendly creatures in it (you too) can't become diseased, resist poison damage, and have advantage on saves against being blinded, charmed, deafened, frightened, paralyzed, poisoned or stunned.", ""),
"Aura of Vitality": ("1 action", "Self (30-foot radius)", "V", "Concentration, up to 1 minute",
  "Healing energy radiates from you. As a bonus action on each of your turns, you can heal one creature in the aura (you included) for 2d6 hit points.", ""),
"Banishing Smite": ("1 bonus action", "Self", "V", "Concentration, up to 1 minute",
  "The next time you hit with a weapon attack before the spell ends, the strike deals an extra 5d10 force damage. If that leaves the target at 50 hit points or fewer, you banish it to a harmless pocket plane until the spell ends (or for good, if it's not from this plane and you keep concentration for the full minute).", ""),
"Beast Bond": ("1 action", "Touch", "V, S, M (a bit of fur wrapped in cloth)", "Concentration, up to 10 minutes",
  "You link minds with a friendly beast with an Intelligence of 3 or less. You can share simple thoughts and feelings, and while it can see you it has advantage on attacks against creatures within 5 feet of you.", ""),
"Beast Sense": ("1 action (ritual)", "Touch", "S", "Concentration, up to 1 hour",
  "You touch a willing beast and use its senses: you see and hear what it does, blind and deaf to your own surroundings until you switch back as an action.", ""),
"Blade of Disaster": ("1 bonus action", "60 feet", "V, S", "Concentration, up to 1 minute",
  "You tear open a blade-shaped rift in reality. When it appears, and as a bonus action on later turns, you can move it up to 30 feet and make up to two melee spell attacks with it against creatures within 5 feet of it. Each hit deals 4d12 force damage, and it scores a critical hit on a 18 or higher, dealing 12d12 extra force damage. It passes through barriers, even a Wall of Force.", ""),
"Blade Ward": ("1 action", "Self", "V, S", "1 round",
  "You trace a ward in the air. Until the end of your next turn you have resistance to bludgeoning, piercing and slashing damage from weapon attacks.", ""),
"Blinding Smite": ("1 bonus action", "Self", "V", "Concentration, up to 1 minute",
  "Your next weapon hit before the spell ends blazes with light: an extra 3d8 radiant damage, and the target must make a Constitution save or be blinded until the spell ends. It repeats the save at the end of each of its turns.", ""),
"Bones of the Earth": ("1 action", "120 feet", "V, S", "Instantaneous",
  "Up to six pillars of stone, each 5 feet across and up to 30 feet tall, burst from the ground at points you choose. A creature on top of one makes a Dexterity save or is lifted with it; one caught between a pillar and a ceiling takes 6d6 bludgeoning and is restrained. Pillars have AC 5 and 30 hit points.", "Two more pillars for each level above 6th."),
"Booming Blade": ("1 action", "Self (5-foot radius)", "S, M (a melee weapon)", "1 round",
  "Make a melee weapon attack as part of the spell. On a hit the target suffers the weapon's normal effects and is sheathed in booming energy: if it willingly moves before your next turn, it takes 1d8 thunder damage and the spell ends. Damage grows at 5th level (1d8 on the hit plus 2d8 if it moves), 11th and 17th.", ""),
"Borrowed Knowledge": ("1 action", "Self", "V, S, M (a book worth 25 gp)", "1 hour",
  "You draw on the knowledge of those who studied before you. Pick one skill you lack; you have proficiency in it for the hour. The spell ends early if you cast it again.", ""),
"Branding Smite": ("1 bonus action", "Self", "V", "Concentration, up to 1 minute",
  "Your next weapon hit before the spell ends brands the target with light: an extra 2d6 radiant damage, and if it was invisible it becomes visible and sheds dim light, and can't turn invisible until the spell ends.", "Extra damage rises by 1d6 for each level above 2nd."),
"Catapult": ("1 action", "60 feet", "S", "Instantaneous",
  "An object weighing 1 to 5 pounds within range flies up to 90 feet in a straight line. A creature in its path makes a Dexterity save or takes 3d8 bludgeoning damage, and the object stops. The object takes the same damage when it hits something.", "Damage rises by 1d8, and the weight limit by 5 pounds, for each level above 1st."),
"Catnap": ("1 action", "30 feet", "S, M (a pinch of sand)", "10 minutes",
  "Up to three willing creatures fall into a magical sleep for the duration. A sleeper wakes early if harmed or shaken awake. A creature that sleeps the full 10 minutes gets the benefit of a short rest, and can't benefit from this spell again until it finishes a long rest.", "One more creature for each level above 3rd."),
"Cause Fear": ("1 action", "60 feet", "V", "Concentration, up to 1 minute",
  "You wake a creature's sense of doom. It makes a Wisdom save or is frightened of you until the spell ends, repeating the save at the end of each of its turns. Constructs and undead are immune.", "One more creature for each level above 1st, all within 30 feet of each other."),
"Ceremony": ("1 hour (ritual)", "Touch", "V, S, M (25 gp of powdered silver, consumed)", "Instantaneous",
  "You lead one religious rite: Atonement (an Insight check lets a repentant creature return to its old alignment), Bless Water, Coming of Age (a d4 bonus to one check for 24 hours), Dedication (a d4 bonus to one save for 24 hours), Funeral Rite (the corpse can't become undead for 7 days), Wedding (couples get +2 AC while fighting side by side for 7 days).", ""),
"Chaos Bolt": ("1 action", "120 feet", "V, S", "Instantaneous",
  "Make a ranged spell attack. On a hit the target takes 2d8 + 1d6 damage; the d8s decide the damage type (acid, cold, fire, force, lightning, poison, psychic, thunder). If both d8s show the same number, the bolt leaps to another creature within 30 feet, and can keep leaping.", "Each target takes 1d6 more damage for each level above 1st."),
"Circle of Power": ("1 action", "Self (30-foot radius)", "V", "Concentration, up to 10 minutes",
  "Divine energy shields you and nearby allies. Friendly creatures in the aura have advantage on saves against spells and magical effects, and when they succeed on a save that would deal half damage, they take none.", ""),
"Cloud of Daggers": ("1 action", "60 feet", "V, S, M (a sliver of glass)", "Concentration, up to 1 minute",
  "Spinning daggers fill a 5-foot cube. A creature takes 4d4 slashing damage when it enters the cube for the first time on a turn or starts its turn there.", "Damage rises by 2d4 for each level above 2nd."),
"Compelled Duel": ("1 bonus action", "30 feet", "V", "Concentration, up to 1 minute",
  "You challenge a creature you can see. It makes a Wisdom save or has disadvantage on attacks against anyone but you, and must save again to move more than 30 feet away from you. The spell ends if you attack someone else, an ally attacks it, or you move more than 30 feet from it.", ""),
"Conjure Barrage": ("1 action", "Self (60-foot cone)", "V, S, M (one piece of ammunition or a thrown weapon)", "Instantaneous",
  "You throw or fire one weapon and it multiplies into a hail of copies. Each creature in a 60-foot cone makes a Dexterity save, taking 3d8 damage of the weapon's type on a failure or half on a success.", ""),
"Conjure Volley": ("1 action", "150 feet", "V, S, M (one piece of ammunition or a thrown weapon)", "Instantaneous",
  "You fire one shot into the air and it becomes a rain of thousands. Each creature in a 40-foot-radius, 20-foot-tall cylinder makes a Dexterity save, taking 8d8 damage of the weapon's type on a failure or half on a success.", ""),
"Control Flames": ("1 action", "60 feet", "S", "Instantaneous or 1 hour",
  "You shape a nonmagical fire no bigger than a 5-foot cube: spread it 5 feet, put it out, make it twice as bright or dim, or shape simple figures in it for an hour. Up to three non-instant effects at once.", ""),
"Control Winds": ("1 action", "300 feet", "V, S", "Concentration, up to 1 hour",
  "You take charge of the air in a 100-foot cube and choose one effect, changeable each turn as an action: Gusts (strong wind in one direction, making flying and ranged attacks harder), Downdraft (flyers make a Strength save or are pushed down; fliers land), or Updraft (a rising wind that slows falls and helps jumps).", ""),
"Cordon of Arrows": ("1 action", "5 feet", "V, S, M (four or more arrows or bolts)", "8 hours",
  "You plant four pieces of ammunition in the ground. Whenever a creature other than those you name comes within 30 feet of them for the first time on a turn or ends its turn there, one flies up at it: it makes a Dexterity save or takes 1d6 piercing damage. The spell ends when the ammunition runs out.", "Two more pieces of ammunition for each level above 2nd."),
"Create Bonfire": ("1 action", "60 feet", "V, S", "Concentration, up to 1 minute",
  "A bonfire springs up in a 5-foot square on the ground. A creature in it when it appears, or that enters it or ends its turn there, makes a Dexterity save or takes 1d8 fire damage. It lights flammable objects. Damage grows to 2d8 at 5th level, 3d8 at 11th and 4d8 at 17th.", ""),
"Create Homunculus": ("1 hour", "Touch", "V, S, M (clay, ash and mandrake root, and a jewel-encrusted dagger worth 1,000 gp)", "Instantaneous",
  "You cut yourself with the dagger, taking 2d4 piercing damage that can't be reduced, and your blood brings the components to life as a homunculus: a tiny, loyal construct. You share a telepathic link with it, and while you're on the same plane you can see and hear through it. You can have only one at a time.", ""),
"Create Magen": ("1 hour", "Touch", "V, S, M (a vial of quicksilver worth 500 gp and a life-sized doll, both consumed, plus an intricate crystal rod worth 1,500 gp that isn't)", "Instantaneous",
  "You make a magen: an artificial person who obeys you. Choose the type: demos (a soldier), galvan (it flies and fires lightning) or hypnos (it bends minds). It serves until destroyed. Your hit point maximum drops by the magen's challenge rating × 10 while it exists.", ""),
"Create Spelljamming Helm": ("1 action", "Touch", "V, S, M (a crystal rod worth 5,000 gp, consumed)", "Instantaneous",
  "You turn a Large or smaller chair you touch into a spelljamming helm. A creature with the ability to cast spells who sits in it can move a ship through the air and the void. (In Avarenth, the DM decides whether such magic even works here.)", ""),
"Crown of Madness": ("1 action", "120 feet", "V, S", "Concentration, up to 1 minute",
  "A twisted crown of jagged iron appears on a humanoid you can see. It makes a Wisdom save or is charmed by you: before moving on each of its turns, it must make a melee attack against a creature of your choice that you can see. You must use your action each turn to keep control or the spell ends. It repeats the save at the end of each turn.", ""),
"Crown of Stars": ("1 action", "Self", "V, S", "1 hour",
  "Seven star-like motes orbit your head. As a bonus action you can fling one at a creature within 120 feet: a ranged spell attack dealing 4d12 radiant damage. While four or more remain, they shed bright light.", "Two more motes for each level above 7th."),
"Vanguard's Mantle": ("1 action", "Self (30-foot radius)", "V", "Concentration, up to 1 minute",
  "Holy power radiates from you. Each friendly creature in the aura (you too) deals an extra 1d4 radiant damage when it hits with a weapon attack.", ""),
"Danse Macabre": ("1 action", "60 feet", "V, S", "Concentration, up to 1 hour",
  "Up to five Small or Medium corpses within range rise as zombies or skeletons under your control. You can command them all as a bonus action. They add your spellcasting modifier to attack and damage rolls. They collapse when the spell ends.", "Two more corpses for each level above 5th."),
"Dark Star": ("1 action", "150 feet", "V, S, M (a shard of onyx and a drop of the caster's blood)", "Concentration, up to 1 minute",
  "A 40-foot-radius sphere of crushing darkness and silence forms at a point you choose. It is difficult terrain, nothing can see or hear into or out of it, and a creature that enters or starts its turn there makes a Constitution save, taking 8d10 force damage on a failure or half on a success. A creature reduced to 0 hit points by it is crushed to nothing.", ""),
"Dawn": ("1 action", "60 feet", "V, S, M (a sunburst pendant worth 100 gp)", "Concentration, up to 1 minute",
  "A 30-foot-radius, 40-foot-high cylinder of sunlight shines at a point you choose. Each creature in it when it appears makes a Constitution save, taking 4d10 radiant damage on a failure or half on a success; it saves again whenever it ends its turn there. You can move the cylinder up to 60 feet as a bonus action.", ""),
"Destructive Wave": ("1 action", "Self (30-foot radius)", "V", "Instantaneous",
  "You strike the ground and divine energy rolls out. Each creature you choose within 30 feet makes a Constitution save. On a failure it takes 5d6 thunder plus 5d6 radiant or necrotic damage (your choice) and is knocked prone. On a success it takes half and stays standing.", ""),
"Distort Value": ("1 minute", "Touch", "V", "8 hours",
  "You make an object up to a 1-foot cube look worth twice as much, or half as much, as it really is. A creature examining it can see through the illusion with an Investigation check against your spell save DC.", "The object can be 1 foot larger on each side for each level above 1st."),
"Draconic Transformation": ("1 bonus action", "Self", "V, M (a statuette of a dragon worth 500 gp)", "Concentration, up to 1 minute",
  "You take on draconic traits: blindsight 30 feet, spectral wings that give you a flying speed of 60 feet, and a breath of shimmering energy you can exhale when you cast it and as a bonus action on later turns: a 60-foot cone, Dexterity save, 6d8 force damage, half on a success.", ""),
"Dream of the Blue Veil": ("10 minutes", "20 feet", "V, S, M (a magic item or willing creature from the destination world)", "6 hours",
  "You and up to eight willing creatures fall into a dream of another world (one you know of, through an item or creature from there). At the end of the dream you all appear there, physically, in a place linked to the item or creature. The DM decides where that world even is.", ""),
"Druid Grove": ("10 minutes", "Touch", "V, S, M (mistletoe, consumed)", "24 hours",
  "You awaken the spirits of an area up to a 90-foot cube of nature to guard it. Choose from: solid fog, grasping undergrowth, grove guardians (animated trees), an additional spell effect (gust of wind, spike growth, etc.), or difficult terrain. The grove knows friends from foes as you say. Cast it in the same place every day for a year and it becomes permanent.", ""),
"Dust Devil": ("1 action", "60 feet", "V, S, M (a pinch of dust)", "Concentration, up to 1 minute",
  "A 5-foot-cube whirlwind forms. Each creature that ends its turn within 5 feet of it makes a Strength save, taking 1d8 bludgeoning damage and being pushed 10 feet away on a failure, or half damage only on a success. You can move it 30 feet as a bonus action; over sand or dust it blinds things in a 10-foot cloud.", "Damage rises by 1d8 for each level above 2nd."),
"Earth Tremor": ("1 action", "Self (10-foot radius)", "V, S", "Instantaneous",
  "You make the ground shake. Each creature other than you within 10 feet makes a Dexterity save, taking 1d6 bludgeoning damage and falling prone on a failure. Loose earth or stone in the area becomes difficult terrain.", "Damage rises by 1d6 for each level above 1st."),
"Earthbind": ("1 action", "300 feet", "V", "Concentration, up to 1 minute",
  "Yellow strips of magic bind a flying creature you can see. It makes a Strength save or its flying speed becomes 0; if it's in the air it drifts down 60 feet a round until it lands.", ""),
"Elemental Bane": ("1 action", "90 feet", "V, S", "Concentration, up to 1 minute",
  "Choose acid, cold, fire, lightning or thunder. A creature you can see makes a Constitution save or, for the duration, takes an extra 2d6 damage of that type the first time each turn it's hit by it, and loses any resistance to it.", "One more creature for each level above 4th."),
"Elemental Weapon": ("1 action", "Touch", "V, S", "Concentration, up to 1 hour",
  "A nonmagical weapon becomes magical: +1 to attack rolls and an extra 1d4 damage of a type you choose (acid, cold, fire, lightning or thunder).", "+2 and 2d4 at 5th or 6th level; +3 and 3d4 at 7th and up."),
"Encode Thoughts": ("1 action", "Self", "S", "Up to 8 hours",
  "You pull a memory, idea or message out of your head and shape it into a thread of thought that can be held. Another creature with this spell can read it, or you can use it as the dream-link for some magic. It fades after 8 hours.", ""),
"Enemies Abound": ("1 action", "120 feet", "V, S", "Concentration, up to 1 minute",
  "You fill a creature's mind with suspicion. It makes an Intelligence save or loses the ability to tell friend from foe: every creature it can see is an enemy to it, and when it attacks it picks its target at random among those in reach. It repeats the save each time it takes damage.", ""),
"Enervation": ("1 action", "60 feet", "V, S", "Concentration, up to 1 minute",
  "A tendril of darkness latches onto a creature. It makes a Dexterity save. On a success it takes 2d8 necrotic damage and the spell ends. On a failure it takes 4d8 now and again on each of your turns as an action, and you regain half the necrotic damage as hit points. Constructs and undead aren't affected.", "Damage rises by 1d8 for each level above 5th."),
"Erupting Earth": ("1 action", "120 feet", "V, S, M (a piece of obsidian)", "Instantaneous",
  "The ground at a point erupts. Each creature in a 20-foot cube makes a Dexterity save, taking 3d12 bludgeoning damage on a failure or half on a success. The ground there becomes difficult terrain until cleared.", "Damage rises by 1d12 for each level above 3rd."),
"Far Step": ("1 bonus action", "Self", "V", "Concentration, up to 1 minute",
  "You teleport up to 60 feet to a space you can see, and can do so again as a bonus action on each turn until the spell ends.", ""),
"Fast Friends": ("1 action", "30 feet", "V", "Concentration, up to 1 hour",
  "A humanoid you can see makes a Wisdom save or is charmed by you and will do reasonable tasks you ask, as long as they aren't dangerous or against its nature. If you or your friends harm it, the spell ends.", "One more humanoid for each level above 3rd."),
"Feeblemind": ("1 action", "150 feet", "V, S, M (a handful of clay, crystal, glass or mineral spheres)", "Instantaneous",
  "You blast a creature's mind. It takes 4d6 psychic damage and makes an Intelligence save. On a failure its Intelligence and Charisma scores drop to 1: it can't cast spells, use magic items, understand language or talk sensibly, though it knows its friends. It repeats the save every 30 days. Greater Restoration, Heal or Wish ends it. (The SRD's Befuddlement is the newer, lighter version.)", ""),
"Feign Death": ("1 action (ritual)", "Touch", "V, S, M (a pinch of graveyard dirt)", "1 hour",
  "You put a willing creature into a deathlike state. It looks dead to any inspection, is blinded and incapacitated, its speed drops to 0, it resists all damage but psychic, and disease and poison in it are paused. You can end it early.", ""),
"Festering Blast": None,
"Find Greater Steed": ("10 minutes", "30 feet", "V, S", "Instantaneous",
  "You summon a loyal, intelligent spirit in the form of a griffon, pegasus, peryton, dire wolf, rhinoceros or saber-toothed tiger. It serves as your mount, can speak telepathically with you, and when you cast a spell targeting only yourself you can have it affect the steed too. Only one such steed at a time.", ""),
"Platinum Ward": ("1 bonus action", "60 feet", "V, S, M (a platinum-plated dragon scale worth 500 gp)", "Concentration, up to 1 minute",
  "A field of silvery light surrounds one creature: half cover, resistance to acid, cold, fire, lightning and poison damage, and evasion-like protection against Dexterity saves for half damage. As a bonus action on later turns, you can move the shield to another creature within 60 feet.", ""),
"Flame Arrows": ("1 action", "Touch", "V, S", "Concentration, up to 1 hour",
  "You touch a quiver of up to twelve arrows or bolts. Each one fired deals an extra 1d6 fire damage, then the magic leaves it.", "Two more pieces of ammunition for each level above 3rd."),
"Flock of Familiars": ("1 minute", "Touch", "V, S", "Concentration, up to 1 hour",
  "You summon three spirits that take familiar forms of your choice, as if from Find Familiar. They obey you and can deliver touch spells. You share senses with one at a time.", "One more familiar for each level above 2nd."),
"Favored Fortune": ("1 minute", "60 feet", "V, M (a white pearl worth 100 gp, consumed)", "1 hour",
  "You give a willing creature a glimpse of the future. Once during the hour it can roll an extra d20 for an attack, check or save, or when it's attacked, and choose which d20 to use.", "One more creature for each level above 2nd."),
"Fount of Moonlight": ("1 action", "Self", "V, S", "Concentration, up to 10 minutes",
  "Cool moonlight wraps you and sheds light in 20 feet. You have resistance to radiant damage, your melee attacks deal an extra 2d6 radiant, and when a creature within 60 feet hits you, you can use your reaction to force it to make a Constitution save or be blinded until the end of your next turn.", ""),
"Fractured Awareness": None,
"Friends": ("1 action", "Self", "S, M (a small amount of makeup)", "Concentration, up to 1 minute",
  "You have advantage on Charisma checks against one non-hostile creature for the duration. When it ends, the creature knows you used magic on it and may well turn hostile.", ""),
"Frost Fingers": ("1 action", "Self (15-foot cone)", "V, S", "Instantaneous",
  "Freezing cold pours from your fingertips. Each creature in a 15-foot cone makes a Constitution save, taking 2d8 cold damage on a failure or half on a success. Water in the cone freezes to a depth of 1 inch.", "Damage rises by 1d8 for each level above 1st."),
"Frostbite": ("1 action", "60 feet", "V, S", "Instantaneous",
  "Frost forms on a creature you can see. It makes a Constitution save or takes 1d6 cold damage and has disadvantage on its next weapon attack before the end of its next turn. Damage grows to 2d6 at 5th level, 3d6 at 11th and 4d6 at 17th.", ""),
}
